questions.q:
Quelle commande permet de renommer une table dans Oracle ?

- A. RENAME TABLE ancienne_table TO nouvelle_table;
- B. ALTER TABLE ancienne_table RENAME TO nouvelle_table;
- C. UPDATE ancienne_table SET NAME = nouvelle_table;
- D. CHANGE TABLE ancienne_table TO nouvelle_table;

questions.a:
CREATE OR REPLACE TRIGGER trg_bloquercommentaire
BEFORE INSERT ON commentaire
FOR EACH ROW
DECLARE
  v_statut contenu.statut%TYPE;
BEGIN
  IF :NEW.note IS NULL OR :NEW.note NOT BETWEEN 0 AND 5 THEN
    RAISE_APPLICATION_ERROR(-20001, 'La note doit etre comprise entre 0 et 5');
  END IF;

  BEGIN
    SELECT statut INTO v_statut FROM contenu WHERE id_contenu = :NEW.id_contenu;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      RAISE_APPLICATION_ERROR(-20003, 'Contenu inexistant');
  END;

  IF v_statut != 'valide' THEN
    RAISE_APPLICATION_ERROR(-20002, 'Le contenu n''est pas valide');
  END IF;
END;
/
- BEFORE INSERT FOR EACH ROW : on refuse avant l'écriture, avec :NEW.
- La table lue (contenu) n'est pas la table du trigger (commentaire) : pas de table en mutation.
- RAISE_APPLICATION_ERROR annule l'insertion.

CREATE OR REPLACE FUNCTION nbcontenusparlangue (p_id_langue IN INT) RETURN NUMBER IS
  v_nb NUMBER;
BEGIN
  SELECT COUNT(*) INTO v_nb
  FROM contenu
  WHERE id_langue = p_id_langue AND statut = 'valide';
  RETURN v_nb;
END nbcontenusparlangue;
/
SELECT nbcontenusparlangue(1) FROM DUAL;
- COUNT(*) ne renvoie jamais NULL : pas besoin de NVL.
- Une fonction retourne une valeur (RETURN) et s'utilise dans un SELECT.

CREATE OR REPLACE PROCEDURE changerlangueutilisateur (
  p_id_utilisateur IN NUMBER,
  p_id_langue      IN NUMBER
) IS
BEGIN
  UPDATE utilisateur
  SET id_langue = p_id_langue
  WHERE id_utilisateur = p_id_utilisateur;

  IF SQL%ROWCOUNT = 0 THEN
    RAISE_APPLICATION_ERROR(-20010, 'Utilisateur inconnu');
  END IF;
END changerlangueutilisateur;
/
EXEC changerlangueutilisateur(5, 2);
- Pas de COMMIT : l'appelant valide.
- SQL%ROWCOUNT = 0 signale un utilisateur inexistant.
- Une langue inexistante est refusée par la clé étrangère (ORA-02291).
